import {poses} from './model.mjs';import {createScene} from './scene.mjs';
export default {id:'migrated-articulated-dial',capabilities:{detail:['compact','standard'],camera:{default:{azimuth:40,elevation:31,padding:24},views:[{azimuth:40,elevation:31}]}},initialState:poses.rest,poses,createScene,clientEntry:new URL('./client.mjs',import.meta.url),render(args){const s=createScene(args);try{const m=s.update(args.state);return {renderer:'three-illustration',viewBox:[0,0,640,470],body:`<g data-scene="three">${s.render()}</g><text class="reading" data-part="static-readout" x="24" y="428">${m.reading}</text><text class="caption" x="24" y="452">Adapted glow and seeded sparks · prescribed motion</text>`,title:'Articulated combination dial',description:'A rotating dial carries a robotic hand. The wheel turns at −¼ dial speed, the pawl oscillates, and three nested finger hinges flex together. Drag around the dial or use arrow keys (Shift: ten steps), Home zeroes the reading and B reverses the pod break sequence. Routed cables, surface details, LED glow and seeded sparks use packaged recipes; the report compares their appearance to the original shaders.'};}finally{s.dispose();}}};
